<?php
namespace Tests\Feature;
use Tests\TestCase;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Support\Facades\DB;
use App\Models\User;
use App\Services\DocumentService;
use Illuminate\Validation\ValidationException;
class PostingTest extends TestCase {
 use RefreshDatabase;
 private User $admin;private int $product;private int $party;
 protected function setUp():void {parent::setUp();$this->seed();$this->admin=User::create(['name'=>'Owner','email'=>'owner@example.test','password'=>'testing-password-123','role'=>'admin']);$this->product=DB::table('products')->insertGetId(['sku'=>'P1','name'=>'Test item','unit'=>'pcs','retail_paise'=>20000,'wholesale_paise'=>18000]);$this->party=DB::table('parties')->insertGetId(['name'=>'Test party']);}
 private function draft(string $kind,string $qty='1',string $price='100',array $extra=[]):int {return app(DocumentService::class)->save(array_replace(['kind'=>$kind,'date'=>'2026-09-20','branch_id'=>1,'warehouse_id'=>1,'party_id'=>$this->party,'tax_treatment'=>'non_gst','state_code'=>'32','price_tier'=>'retail','reason'=>'Test','lines'=>[['product_id'=>$this->product,'quantity'=>$qty,'price'=>$price]]],$extra),$this->admin);}
 private function postDocument(int $id):void {app(DocumentService::class)->post($id,$this->admin);}
 private function balance(string $code):int {return (int)DB::table('ledger_entries as l')->join('accounts as a','a.id','=','l.account_id')->where('a.code',$code)->selectRaw('COALESCE(SUM(debit_paise-credit_paise),0) as n')->value('n');}
 public function test_purchase_sale_and_double_post_are_atomic_and_idempotent():void {$p=$this->draft('purchase','10','100');$this->postDocument($p);$s=$this->draft('sale','3','200');$this->postDocument($s);$this->postDocument($s);$this->assertSame(7000,(int)DB::table('stock_balances')->value('quantity_milli'));$this->assertSame(70000,$this->balance('1200'));$this->assertSame(30000,$this->balance('5000'));$this->assertSame(60000,$this->balance('1100'));$this->assertSame((int)DB::table('ledger_entries')->sum('debit_paise'),(int)DB::table('ledger_entries')->sum('credit_paise'));}
 public function test_unbalanced_journal_rolls_back_posting():void {$a=DB::table('accounts')->where('code','1000')->value('id');$id=$this->draft('journal','1','0',['lines'=>[['account_id'=>$a,'debit'=>'100','credit'=>'0']]]);try{$this->postDocument($id);$this->fail('Unbalanced posting accepted');}catch(ValidationException $e){$this->assertSame('draft',DB::table('documents')->where('id',$id)->value('status'));$this->assertSame(0,DB::table('ledger_entries')->count());}}
 public function test_negative_stock_is_flagged_and_later_cost_settles():void {$sale=$this->draft('sale','2','200');$this->postDocument($sale);$this->assertSame(-2000,(int)DB::table('stock_balances')->value('quantity_milli'));$this->assertNotEmpty(json_decode(DB::table('documents')->where('id',$sale)->value('warnings'),true));$this->postDocument($this->draft('purchase','5','100'));$this->assertSame(3000,(int)DB::table('stock_balances')->value('quantity_milli'));$this->assertSame(30000,$this->balance('1200'));$this->assertSame(20000,$this->balance('5000'));$this->assertSame(30000,(int)DB::table('stock_balances')->value('value_paise'));}
 public function test_receipt_bill_link_does_not_receive_stock_twice():void {$g=$this->draft('goods_receipt','5','100');$this->postDocument($g);$source=DB::table('document_lines')->where('document_id',$g)->first();$bill=$this->draft('purchase','5','100',['related_id'=>$g,'lines'=>[['product_id'=>$this->product,'quantity'=>'5','price'=>'100','source_line_id'=>$source->id]]]);$this->postDocument($bill);$this->assertSame(5000,(int)DB::table('stock_balances')->value('quantity_milli'));$this->assertSame(0,$this->balance('2300'));$this->assertSame(-50000,$this->balance('2000'));}
 public function test_source_over_receipt_is_rejected():void {$po=$this->draft('purchase_order','2','100');$this->postDocument($po);$line=DB::table('document_lines')->where('document_id',$po)->first();$grn=$this->draft('goods_receipt','3','100',['related_id'=>$po,'lines'=>[['product_id'=>$this->product,'quantity'=>'3','price'=>'100','source_line_id'=>$line->id]]]);$this->expectException(ValidationException::class);$this->postDocument($grn);}
 public function test_unregistered_business_cannot_charge_gst():void {$this->expectException(ValidationException::class);$this->draft('sale','1','100',['tax_treatment'=>'taxable']);}
 public function test_posted_document_cannot_be_edited():void {$id=$this->draft('purchase');$this->postDocument($id);$snapshot=app(DocumentService::class)->snapshot($id);$this->expectException(ValidationException::class);app(DocumentService::class)->save(['kind'=>'purchase','date'=>'2026-09-20','branch_id'=>1,'warehouse_id'=>1,'party_id'=>$this->party,'tax_treatment'=>'non_gst','state_code'=>'32','price_tier'=>'retail','version'=>$snapshot['document']['version'],'lines'=>[['product_id'=>$this->product,'quantity'=>'1','price'=>'150']]],$this->admin,$id);}
 public function test_reversal_preserves_original_and_reverses_balances():void {$id=$this->draft('purchase');$this->postDocument($id);$r=app(DocumentService::class)->reverse($id,$this->admin,'Entered twice','2026-09-20');$this->assertSame('reversed',DB::table('documents')->where('id',$id)->value('status'));$this->assertSame($id,DB::table('documents')->where('id',$r)->value('reversal_of'));$this->assertSame(0,$this->balance('1200'));$this->assertGreaterThan(0,DB::table('audit_events')->count());}
 public function test_branch_isolation_and_permission_are_enforced():void {$u=User::create(['name'=>'Restricted','email'=>'staff@example.test','password'=>'testing-password-123','role'=>'staff','permissions'=>['view'],'branch_ids'=>[]]);$id=$this->draft('sale');$this->actingAs($u)->getJson('/api/documents/'.$id)->assertForbidden();$this->actingAs($u)->postJson('/api/documents/'.$id.'/post')->assertForbidden();}
 public function test_session_auth_required():void {$this->getJson('/api/bootstrap')->assertUnauthorized();}
 public function test_period_lock_blocks_posting():void {DB::table('business')->update(['locked_until'=>'2026-09-30']);$id=$this->draft('purchase');$this->expectException(ValidationException::class);$this->postDocument($id);}
 public function test_counter_checkout_is_not_collected_twice():void {$id=$this->draft('sale','1','200');$this->actingAs($this->admin)->postJson('/api/documents/'.$id.'/checkout',['cash_account'=>'1000'])->assertOk();$this->actingAs($this->admin)->postJson('/api/documents/'.$id.'/checkout',['cash_account'=>'1000'])->assertOk();$this->assertSame(20000,$this->balance('1000'));$this->assertSame(0,$this->balance('1100'));}
}
